INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('blind-crown', 'Blind Crown — Nightfall', '1.5.0', 'experimental', 'imported', 'not-integrated', '{"id":"blind-crown","title":"Blind Crown — Nightfall","aliases":["Blind Crown","Classic Blind Volley"],"tags":["strategy","simultaneous-turns","archery","arcade","party","bots","mobile","canvas"],"description":"Private-plan medieval archery for 2–10 contestant slots. Nightfall adds textured diorama arenas, armored knights, torchlight, matching portraits, responsive controls and timed volley effects while preserving Classic rules. One local human with bots; first/third-person default to Canvas 2.5D. Hosted phone multiplayer is not integrated.","players":{"min":2,"max":10},"version":"1.5.0","source":{"status":"imported","paths":["source/index.html","source/original/blind-crown-v1.4.html"],"provenance":"Nightfall v1.5 presentation upgrade from the exact supplied Refined v1.4 game, preserved under source/original/. New original Canvas/SVG art and synthesized audio; no external art/font/music packs added. Current standalone SHA-256: 06a0238b9827cd6f4395ec33cd0b2c8c7ce758bc15135a946ed7c737e53ef0e4. Experimental pinned Three.js remains opt-in and unverified. See assets/README.md.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-ballistix', 'Royal Ballistix — Beach Siege', '0.12.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-ballistix","title":"Royal Ballistix — Beach Siege","aliases":["Royal Ballistix","Ballistix","Beach Siege","Royal Ballistix Beach Siege"],"tags":["physics","ball-deflection","survival","arcade","party","bots","mobile","canvas"],"description":"Radial ball-deflection survival game for 2–10 contestants. One local player can defend a gate with movement, Magnet, Pulse and Run while AI bots fill remaining seats; arena size is adjustable and phone/network transport is not yet integrated.","players":{"min":2,"max":10},"version":"0.12.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Imported unchanged from edmondsonedits/CALLBACK commit ed09d25b690b36b397516e4d77437e3dd21247c8 (game-modes/royal-ballistix/index.html). Upstream repository license: Apache-2.0.","url":"https://github.com/edmondsonedits/CALLBACK/blob/ed09d25b690b36b397516e4d77437e3dd21247c8/game-modes/royal-ballistix/index.html"},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-roller-ruckus', 'Royal Roller Ruckus — Crownway Circuit', '1.4.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-roller-ruckus","title":"Royal Roller Ruckus — Crownway Circuit","aliases":["Royal Roller Ruckus","Roller Ruckus","Crownway Circuit"],"tags":["racing","physics","momentum","arcade","party","bots","mobile","three-js"],"description":"A 2–10 racer momentum-driven cage race around the vertical Crownway Circuit with collisions, checkpoints, recovery after falls, bot-filled seats, and CALLBACK remote-input hooks.","players":{"min":2,"max":10},"version":"1.4.0","source":{"status":"imported","paths":["source/index.html","source/original/royal_roller_ruckus_v1.4_vertical_crownway.html"],"provenance":"Imported from the user-supplied royal_roller_ruckus_v1.4_vertical_crownway.html. The active standalone build imports Three.js 0.180.0 from jsDelivr at runtime.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-scratch-match', 'Royal Scratch Match', '0.5.0', 'experimental', 'imported', 'not-integrated', '{"id":"royal-scratch-match","title":"Royal Scratch Match","aliases":["Scratch Match","Create Scratch Match"],"tags":["rhythm","music","timing","memory","arcade","bots","mobile"],"description":"Imported v0.5 standalone call-and-response rhythm game for 2–10 contestant slots. One local touch/keyboard player is supported by default, remaining slots can be bot-controlled, and additional human slots can receive inputs through the existing JavaScript API. Room-code phone multiplayer is not yet integrated.","players":{"min":2,"max":10},"version":"0.5.0","source":{"status":"imported","paths":["source/index.html"],"provenance":"Standalone royal_scratch_match_v0.5_ten_player.html created in the user''s ChatGPT CALLBACK project and supplied by the user in this chat for import. Imported without gameplay changes as source/index.html. The runtime has no external asset dependencies; the user explicitly requested this project/repository use.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-sumo', 'Royal Sumo', '0.21.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-sumo","title":"Royal Sumo","aliases":["Sumo","Royal Sumo Crownfall","Crownfall Arena"],"tags":["arena","physics","sumo","arcade","party","bots","three-js"],"description":"A 2–10 fighter shrinking-arena physics sumo game with Bash, Dash, stability, knockouts, dynamic camera work and bot-filled contestant slots. The standalone v0.21 source is imported; online phone-room transport is not yet implemented.","players":{"min":2,"max":10},"version":"0.21.0","controls":{"local":["virtual joystick","hold/release Bash","tap Dash","pause/settings"],"remoteHooks":["moveX/moveY","bashPressed/bashCharge","dashPressed","sequence"]},"source":{"status":"imported","paths":["source/index.html","source/original/royal_sumo_crownfall_v0.21_player_scaled_arena.html","source/vendor/three.module.js","source/vendor/three.core.js"],"provenance":"Royal Sumo/Crownfall Arena v0.21.0 was developed in the user''s ChatGPT CALLBACK project. The exact generated standalone HTML is retained under source/original/. source/index.html differs only by replacing the pinned Three.js 0.180.0 CDN import with the vendored Three.js r180 MIT-licensed build in source/vendor/.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('royal-twisted', 'Royal Twisted — Spiral Keep', '0.5.0', 'experimental', 'imported', 'in-progress', '{"id":"royal-twisted","title":"Royal Twisted — Spiral Keep","aliases":["Royal Twisted","Spiral Keep","Twisted System"],"tags":["obstacle","survival","reaction","arcade","party","bots","mobile","three-js"],"description":"A 2–10 contestant obstacle-survival run around Spiral Keep: jump low cyan rods, duck high coral rods, survive up to seven hits, and race AI or remote-controlled rivals. v0.5 exposes CALLBACK remote-input hooks; the older v0.4 upload is retained as an archive.","players":{"min":2,"max":10},"version":"0.5.0","source":{"status":"imported","paths":["source/index.html","source/original/royal_twisted_spiral_keep_v0.5_original_camera_knockback.html"],"provenance":"Imported from the user-supplied royal_twisted_spiral_keep_v0.5_original_camera_knockback.html. The uploaded v0.4 ten-player build is retained separately under source/archive/ for history. The active build imports Three.js 0.180.0 from jsDelivr at runtime.","url":null},"lifecycle":"experimental","multiplayer":{"status":"in-progress","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
INSERT INTO games (id, title, version, lifecycle, source_status, multiplayer_status, manifest_json) VALUES ('space-bash', 'Space Bash — Orbital Breakout', '1.13.1', 'experimental', 'imported', 'not-integrated', '{"id":"space-bash","title":"Space Bash — Orbital Breakout","aliases":["Space Bash","Orbital Breakout"],"tags":["arena","brawler","physics","destruction","arcade","party","bots","mobile","canvas"],"description":"A self-contained 2–10 contestant arena brawler on a destructible orbital deck: move, grab and throw crates, kick rivals, jump gaps, and outlast CPU opponents. No external runtime assets or network connection are required.","players":{"min":2,"max":10},"version":"1.13.1","source":{"status":"imported","paths":["source/index.html","source/original/space_bash_orbital_breakout_v1.13.1_standalone.html"],"provenance":"Imported from the user-supplied space_bash_orbital_breakout_v1.13.1_standalone.html. The build is intentionally self-contained and does not require external scripts, modules, WebGL, CDN assets, or a network connection.","url":null},"lifecycle":"experimental","multiplayer":{"status":"not-integrated","evidence":[]}}') ON CONFLICT(id) DO UPDATE SET title=excluded.title, version=excluded.version, lifecycle=excluded.lifecycle, source_status=excluded.source_status, multiplayer_status=excluded.multiplayer_status, manifest_json=excluded.manifest_json;
